  StartCoroutine(LoadSounds());ApplyStudio();screen="home";Refresh();booted=true;if(store.error!=null)Toast(store.error,10);if(visual)StartCoroutine(AtelierQA.Visual(this));else if(qa)StartCoroutine(AtelierQA.Run(this));
 }
 IEnumerator LoadSounds(){var list=new[]{"paint","file","brush","wipe","gel","drill","fan","pick-0","done-0","sticker-0","tip-0","lamp-0","reward-0","coin-0","camera-0"};foreach(var id in list){var req=Resources.LoadAsync<AudioClip>("NailAtelier/Audio/"+id);yield return req;if(req.asset!=null)audioClips[id]=(AudioClip)req.asset;}}
 public void PlaySound(string id){if(data.muted)return;AudioClip clip;if(audioClips.TryGetValue(id,out clip))sfx.PlayOneShot(clip);}
 public void Music(int track){data.track=(track+6)%6;StartCoroutine(StartMusic());ScheduleSave();}
 IEnumerator StartMusic(){var req=Resources.LoadAsync<AudioClip>("NailAtelier/Music/track-"+(data.track+1));yield return req;music.clip=(AudioClip)req.asset;music.volume=data.muted?0:data.volume;music.Play();}
 void Update(){if(!booted)return;if(oldW!=Screen.width||oldH!=Screen.height){oldW=Screen.width;oldH=Screen.height;Refresh();}if(toastObject&&Time.unscaledTime>toastUntil)toastObject.SetActive(false);if(savePending&&Time.unscaledTime>saveAt){savePending=false;Save();}if(contact.isPlaying&&Time.unscaledTime-lastContact>.12f)contact.Stop();if(music.clip&&!music.isPlaying&&music.time>music.clip.length-.5f)Music(data.track+1);if(lampRemaining>0){lampRemaining-=Time.unscaledDeltaTime;if(lampRemaining<=0)FinishLamp();}if(UnityEngine.Input.GetKey(KeyCode.LeftControl)||UnityEngine.Input.GetKey(KeyCode.RightControl)){if(UnityEngine.Input.GetKeyDown(KeyCode.Z))Undo(false);if(UnityEngine.Input.GetKeyDown(KeyCode.Y))Undo(true);}if(UnityEngine.Input.GetKeyDown(KeyCode.Escape)&&overlay.gameObject.activeSelf)CloseModal();}
 void OnApplicationFocus(bool focus){if(booted&&!focus){ReleaseContact();if(lampRemaining>0)InterruptLamp();Save();}}
 void OnApplicationQuit(){if(booted)Save();}
 public void Save(){try{store.Save(data);UpdateWallet();}catch(Exception e){Toast(e.Message,8);}}
 void ScheduleSave(){savePending=true;saveAt=Time.unscaledTime+.4f;}
 public void Transaction(Action change){var previous=Rules.Copy(data);try{change();store.Save(data);UpdateWallet();}catch(Exception e){data=previous;Toast("操作未保存："+e.Message,8);}}
 void Remember(){if(Design==null)return;undo.Push(JsonUtility.ToJson(freeMode?(object)data.free:data.session));if(undo.Count>40){var a=undo.Take(40).Reverse().ToArray();undo.Clear();foreach(var x in a)undo.Push(x);}redo.Clear();}
 void Undo(bool next){if(lampRemaining>0||currentModal!=null)return;var from=next?redo:undo;var to=next?undo:redo;if(from.Count==0)return;to.Push(JsonUtility.ToJson(freeMode?(object)data.free:data.session));if(freeMode)data.free=JsonUtility.FromJson<Design>(from.Pop());else data.session=JsonUtility.FromJson<Session>(from.Pop());selected=null;Refresh();ScheduleSave();}
 void Edit(Action change,bool refresh=true){Remember();change();selected=selected!=null?Design.nails[active].decorations.FirstOrDefault(x=>x.id==selected.id):null;ApplyNails();if(refresh)Refresh();ScheduleSave();}
 public void Select(int i){active=i;view.active=i;selected=null;sticker=null;Refresh();if(screen=="work")view.Focus("detail");}
 public void Accept(string id){var c=catalog.Find(id);if(c==null||!Rules.Access(catalog,data,c)){Toast("请先完成上一课或这位顾客的首次服务。");return;}Transaction(()=>data.session=Rules.Create(c,Rules.Visits(catalog,data,c)));freeMode=false;active=c.route=="repair"?6:2;screen="plan";undo.Clear();redo.Clear();CloseModal();Refresh();ShowConsultation();}
 public void Answer(string topic){if(!data.session.consultation.Contains(topic)){data.session.consultation.Add(topic);Save();}ShowConsultation(topic);}
 public void BeginService(){var missing=Rules.Checks(Who,Design).Where(c=>!c.ok).ToArray();if(missing.Length>0){Toast(missing[0].label+"，请继续设计。",5);return;}if(data.session.consultation.Count!=4){ShowConsultation();return;}data.session.phase="work";data.session.step=0;screen="work";undo.Clear();redo.Clear();Save();Refresh();view.Focus("both");}
 public void Hit(int i,Vector2 uv,bool down){
  if(currentModal!=null||lampRemaining>0||view.viewOnly||Design==null||screen=="home"||screen=="studio")return;
  if(!freeMode&&Who.route=="repair"&&i!=6){Toast("只维修右食指，其余九指保留。");return;}
  if(screen=="plan"||freeMode){
   if(active!=i){active=i;selected=null;Refresh();return;}var n=Design.nails[i];
   if(down){Remember();contactDown=true;previousUV=uv;stroke=null;if(sticker!=null){if(n.decorations.Count>=18){Toast("每指最多18枚装饰。");return;}selected=new Deco{id=Rules.Id(),type=sticker,u=uv.x,v=uv.y,scale=1};Rules.Constrain(n,selected);n.decorations.Add(selected);sticker=null;PlaySound("sticker-0");ApplyNails();RebuildSide();ScheduleSave();return;}if(drawTool=="select")selected=n.decorations.LastOrDefault(d=>!d.hidden&&Vector2.Distance(new Vector2(d.u,d.v),uv)<.22f);else if(drawTool=="paint"||drawTool=="erase"){if(n.strokes.Count>=200){Toast("笔迹已满，请导出作品。");return;}stroke=new Stroke{kind=drawTool,color=brushColor,size=brushSize};n.strokes.Add(stroke);}else if(drawTool=="magnet"){n.magnet.u=uv.x;n.magnet.angle=(uv.y-.5f)*2;}}
   if(!down&&!contactDown)return;
   if(selected!=null&&drawTool=="select"&&!selected.locked){selected.u=uv.x;selected.v=uv.y;Rules.Constrain(n,selected);}if(stroke!=null)stroke.points.Add(new InkPoint(uv.x,uv.y));if(drawTool=="magnet"){n.magnet.u=uv.x;n.magnet.angle=(uv.y-.5f)*2;}ApplyOne(i);UpdatePlanImages();ScheduleSave();return;
  }
  if(screen!="work"||Step=="finish"||Step.StartsWith("cure"))return;
  if(i!=active){active=i;Refresh();view.Focus("detail");return;}
  var work=data.session.work[i];if(work.done.Contains(Step))return;
  if(down){Remember();contactDown=true;previousUV=uv;work.path.Clear();}
  if(!contactDown)return;
  float travel=Vector2.Distance(previousUV,uv);if(Step=="inspect"){CompleteFinger(i);return;}
  if(Step=="fit"){if(!down&&travel>.005f)work.travel+=travel;if(uv.y<.25f&&work.travel>.35f&&work.fitWidth==ExpectedWidth(i)&&work.fitCurve==(Who.curve>1.1f?1:0))work.bondFront=1;}
  else if(Step=="bond"){if(down){work.bondFront=uv.y<.25f?uv.y:0;work.travel=uv.y<.25f?1:0;}if(work.travel>0&&uv.y<=work.bondFront+.23f)work.bondFront=Mathf.Max(work.bondFront,uv.y);if(work.bondFront>.88f)CompleteFinger(i);}
  else if(Step=="file"){if(uv.y>.68f&&Mathf.Abs(uv.x-previousUV.x)>.008f)work.travel+=Mathf.Abs(uv.x-previousUV.x);if(work.travel>1.1f)CompleteFinger(i);}
  else if(Step=="magnet"){Design.nails[i].magnet.u=uv.x;Design.nails[i].magnet.angle=(uv.y-.5f)*2;ApplyOne(i);}
  else if(Step=="decor"){var n=Design.nails[i];for(int j=0;j<n.decorations.Count;j++){var d=n.decorations[j];if(!d.hidden&&Vector2.Distance(uv,new Vector2(d.u,d.v))<.2f&&!work.coverage.Contains(j))work.coverage.Add(j);}if(n.decorations.Where(d=>!d.hidden).Count()<=work.coverage.Count)CompleteFinger(i);}
  else if(travel>.006f){int cell=Mathf.Clamp((int)(uv.y*8),0,7)*6+Mathf.Clamp((int)(uv.x*6),0,5);if(!work.coverage.Contains(cell))work.coverage.Add(cell);work.path.Add(new InkPoint(uv.x,uv.y));view.Mask(i,uv,.15f);if(work.coverage.Count>=26)CompleteFinger(i);}
  if(travel>.005f){lastContact=Time.unscaledTime;if(!data.muted){string sound=catalog.stages.First(s=>s.id==Step).sound;AudioClip clip;if(audioClips.TryGetValue(sound,out clip)&&(!contact.isPlaying||contact.clip!=clip)){contact.clip=clip;contact.Play();}}}previousUV=uv;ApplyOne(i);ScheduleSave();
 }
 public void ReleaseContact(){if(contact)contact.Stop();if(!booted||!contactDown)return;if(!freeMode&&screen=="work"&&Step=="fit"&&data.session.work[active].bondFront>=1)CompleteFinger(active);contactDown=false;stroke=null;if(Design!=null&&(screen=="plan"||freeMode))RebuildSide();}
 int ExpectedWidth(int i)=>(i%5==0?3:i%5==4?0:1)+(Who.width>1.1f?1:0);
 public void CompleteFinger(int i){var w=data.session.work[i];if(!w.done.Contains(Step)){w.done.Add(Step);PlaySound("done-0");Toast(Rules.Finger(i)+" · "+catalog.stages.First(s=>s.id==Step).name+"完成");}contactDown=false;ApplyOne(i);RebuildSide();BuildFingers();ScheduleSave();}
 public void Assist(){var ids=Rules.Targets(data.session).Where(i=>i/5==active/5).ToArray();if(!ids.Any(i=>data.session.work[i].done.Contains(Step))){Toast("先亲手完成本手一指。");return;}Remember();foreach(int i in ids)if(!data.session.work[i].done.Contains(Step))data.session.work[i].done.Add(Step);ApplyNails();Refresh();ScheduleSave();}
 public void NextStage(){if(!Rules.Targets(data.session).All(i=>data.session.work[i].done.Contains(Step))){Toast("先完成本阶段。");return;}data.session.step++;foreach(int i in Rules.Targets(data.session)){var w=data.session.work[i];w.coverage.Clear();w.path.Clear();w.travel=0;w.bondFront=0;view.ResetMask(i);}undo.Clear();redo.Clear();active=Rules.Targets(data.session)[0];Save();Refresh();view.Focus("both");}
 public void StartLamp(int hand){if(lampRemaining>0||!Step.StartsWith("cure"))return;var ids=Rules.Targets(data.session).Where(i=>i/5==hand).ToArray();if(ids.Length==0){Toast("本手无需维修固化。");return;}if(ids.All(i=>data.session.work[i].done.Contains(Step))){Toast("这只手本轮已固化。");return;}lampHand=hand;lampStep=Step;lampRemaining=4.5f;view.SetLamp(true,hand);PlaySound("lamp-0");RebuildSide();}
 public void InterruptLamp(){lampRemaining=0;lampHand=-1;view.SetLamp(false);Toast("提前取手，本手本轮未固化。");RebuildSide();}
 void FinishLamp(){foreach(int i in Rules.Targets(data.session).Where(i=>i/5==lampHand))if(!data.session.work[i].done.Contains(lampStep))data.session.work[i].done.Add(lampStep);lampHand=-1;view.SetLamp(false);Save();Refresh();}
 public void Deliver(){if(!Rules.Complete(Who,data.session)){Toast("还有要求或施工步骤未完成。");return;}data.session.phase="result";screen="result";undo.Clear();redo.Clear();Save();Refresh();view.Focus("both");ShowCheckout();}
 public void Claim(){bool existed=data.receipts.Any(r=>r.id==data.session.id);Transaction(()=>Rules.Claim(catalog,data));if(!existed&&data.receipts.Any(r=>r.id==data.session.id)){PlaySound("reward-0");PlaySound("coin-0");Toast("收入已入账 +"+Rules.Reward(Who,data.session).total+" 金币",5);}ShowCheckout();}
 public void SaveAlbum(){var d=Design;Transaction(()=>{var old=data.album.FirstOrDefault(x=>x.id==d.id);if(old!=null){old.design=Rules.Copy(d);old.name=d.name;}else data.album.Insert(0,new AlbumEntry{id=d.id,name=d.name,client=freeMode?null:Who.id,score=100,design=Rules.Copy(d)});});ApplyStudio();Toast("完整十指已收藏。");}
 public void ApplyOne(int i){var n=Rules.Copy(Design.nails[i]);float reveal=1,old=0,dirt=0,dust=0;if(!freeMode&&data.session.phase=="work"){var w=data.session.work[i];bool repair=Who.route=="repair"&&i!=6;if(!repair){reveal=w.done.Contains("color")?1:0;old=!string.IsNullOrEmpty(Who.old)&&!w.done.Contains("remove")?1:0;dirt=Who.dirty&&!w.done.Contains("clean")?1:0;dust=w.done.Contains("file")&&!w.done.Contains("dust")?1:0;if(Step!="color"&&reveal==0)n.@base="#e8b8ad";if(!w.done.Contains("decor")&&Step!="decor")n.decorations.Clear();if(!w.done.Contains("build"))n.build=0;}}view.Apply(i,n,reveal,old,dirt,dust);}
 public void ApplyNails(){if(Design!=null)for(int i=0;i<10;i++)ApplyOne(i);else{var look=catalog.Find("trend-liquid").reference;for(int i=0;i<10;i++)view.Apply(i,look.nails[i]);}}
 public void ApplyStudio()=>view.Studio(data);
 public void Refresh(){if(!root)return;view.active=active;view.planMode=screen=="plan";view.viewOnly=screen=="home"||screen=="studio"||screen=="result";ApplyNails();Layout();BuildHeader();BuildFingers();BuildStage();RebuildSide();UpdateWallet();}
 public void Resume(){if(data.session==null)return;freeMode=false;screen=data.session.phase;CloseModal();Refresh();if(data.session.consultation.Count<4)ShowConsultation();}
