 void SetupUI(){gameObject.name="AtelierApp";var go=new GameObject("Atelier Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scale=go.GetComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1440,960);scale.matchWidthOrHeight=.5f;root=go.GetComponent<RectTransform>();new GameObject("Event System",typeof(EventSystem),typeof(StandaloneInputModule));header=Panel(root,"Header",Paper);sidebar=Panel(root,"Sidebar",Paper);fingers=Panel(root,"Fingers",Paper);stageLabel=Panel(root,"Stage label",Color.clear);planBoard=Panel(root,"Design board",Rules.ColorOf("#f3ecdf"));overlay=Panel(root,"Modal overlay",new Color(.25f,.2f,.18f,.55f));overlay.gameObject.SetActive(false);toastObject=Panel(root,"Status",Rules.ColorOf("#624e43")).gameObject;toastText=Text(toastObject.transform,"",15,Color.white,TextAnchor.MiddleCenter);toastText.rectTransform.anchorMin=Vector2.zero;toastText.rectTransform.anchorMax=Vector2.one;toastText.rectTransform.offsetMin=new Vector2(12,8);toastText.rectTransform.offsetMax=new Vector2(-12,-8);toastObject.SetActive(false);Layout();}
