 void BuildStage(){Clear(stageLabel);planBoard.gameObject.SetActive(screen=="plan");Clear(planBoard);if(screen=="home"||screen=="studio")return;string title=freeMode?"我的十指 · 自由创作":screen=="plan"?"十指灵感设计":screen=="result"?"交付作品":catalog.stages.First(s=>s.id==Step).name;var t=Text(stageLabel,title,24,Ink);Rect(t.rectTransform,Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);if(screen=="plan")BuildPlan();}
