 IEnumerable<int> Editable()=>!freeMode&&Who.route=="repair"?new[]{6}:Enumerable.Range(0,10);
 void SetHex(string value,Action<string> setter){Color c;if(value.Length==7&&ColorUtility.TryParseHtmlString(value,out c))Edit(()=>setter(value.ToLowerInvariant()));else Toast("请填写 #RRGGBB 色值。");}
 void Choice(Transform p,string label,string[] values,string selectedValue,Func<string,string> name,Action<string> choose){Label(p,label,13,Muted);var row=Row(p,38);for(int i=0;i<values.Length;i++){if(i>0&&i%3==0)row=Row(p,38);string v=values[i];Button(row,label+"-"+v,name(v),()=>choose(v),v==selectedValue);}}
 void Slider(Transform p,string title,float value,float min,float max,Action<float> change,bool update){var label=Text(p,title+"  "+value.ToString("0.00"),13,Muted);var rt=Panel(p,"Slider "+title,Rules.ColorOf("#decfc0"));rt.gameObject.AddComponent<LayoutElement>().minHeight=26;var s=rt.gameObject.AddComponent<Slider>();s.minValue=min;s.maxValue=max;var fill=Panel(rt,"Fill",Rose);Rect(fill,Vector2.zero,Vector2.one,new Vector2(0,7),new Vector2(0,-7));s.fillRect=fill;var handle=Panel(rt,"Handle",Rules.ColorOf("#7e5b5e"));Rect(handle,new Vector2(0,0),new Vector2(0,1),new Vector2(-6,1),new Vector2(6,-1));s.handleRect=handle;s.targetGraphic=handle.GetComponent<Image>();s.value=value;s.onValueChanged.AddListener(v=>{if(!contactDown){Remember();contactDown=true;}change(v);label.text=title+"  "+v.ToString("0.00");if(update){ApplyOne(active);UpdatePlanImages();}ScheduleSave();});var trigger=rt.gameObject.AddComponent<EventTrigger>();var e=new EventTrigger.Entry{eventID=EventTriggerType.PointerUp};e.callback.AddListener(_=>contactDown=false);trigger.triggers.Add(e);}
 void Toggle(Transform p,string title,bool value,Action<bool> change){Button(p,title,(value?"✓ ":"○ ")+title,()=>change(!value),value);}
 InputField Input(Transform p,string title,string value,Action<string> commit){Label(p,title,12,Muted);var rt=Panel(p,title,Color.white);rt.gameObject.AddComponent<LayoutElement>().minHeight=38;var input=rt.gameObject.AddComponent<InputField>();var text=Text(rt,value,14,Ink,TextAnchor.MiddleLeft);Rect(text.rectTransform,Vector2.zero,Vector2.one,new Vector2(9,2),new Vector2(-9,-2));input.textComponent=text;input.text=value;input.onEndEdit.AddListener(v=>{if(v!=value)commit(v);});return input;}
 void WorkUI(Transform p){Label(p,Who.name+" · "+Who.title,20);if(Who.lesson>0)Label(p,"学艺 "+Who.lesson+" / 5 · "+catalog.lessons[Who.lesson-1].name,14,Rose);var stage=catalog.stages.First(s=>s.id==Step);Label(p,stage.name,26);Label(p,stage.hint,15,Muted);var ids=Rules.Targets(data.session);Label(p,ids.Count(i=>data.session.work[i].done.Contains(Step))+" / "+ids.Length+" 指完成 · "+Rules.Finger(active),14);Button(p,"workReference","查看已确认的蓝图",()=>ShowReference(Design,"我的十指蓝图"));var views=Row(p);Button(views,"both","双手",()=>view.Focus("both"));Button(views,"detail","单指",()=>view.Focus("detail"));Button(views,"side","侧面",()=>view.Focus("side"));Button(p,"rotate",view.viewOnly?"回到操作":"旋转查看",()=>{view.viewOnly=!view.viewOnly;RebuildSide();});if(lampRemaining>0){Label(p,(lampHand==0?"左":"右")+"手正在固化 · 整手五指一起",20,Rose);Button(p,"interruptLamp","提前取手",InterruptLamp);Button(p,"speedLamp","缩短等待",()=>lampRemaining=Mathf.Min(.3f,lampRemaining));return;}
  if(Step.StartsWith("cure")){Label(p,"三轮照灯分别记录。提前取手不算完成。",13,Muted);var r=Row(p);Button(r,"lampLeft","左手入灯",()=>StartLamp(0),true);Button(r,"lampRight","右手入灯",()=>StartLamp(1),true);}
  else if(Step=="finish"){Button(p,"deliver","检查并交付作品",Deliver,true);return;}
  else{if(Step=="fit"){Choice(p,"甲片宽度",new[]{"0","1","2","3","4"},data.session.work[active].fitWidth.ToString(),v=>new[]{"XS","S","M","L","XL"}[int.Parse(v)],v=>{data.session.work[active].fitWidth=int.Parse(v);ScheduleSave();RebuildSide();});Choice(p,"甲片弧度",new[]{"0","1"},data.session.work[active].fitCurve.ToString(),v=>v=="0"?"自然弧":"高弧",v=>{data.session.work[active].fitCurve=int.Parse(v);ScheduleSave();RebuildSide();});Button(p,"suggestTip","拿取适合本指的候选甲片",()=>{var w=data.session.work[active];w.fitWidth=ExpectedWidth(active);w.fitCurve=Who.curve>1.1f?1:0;RebuildSide();});Label(p,"按住甲片，从指尖拖到甲根（靠手腕侧）后松手。",13,Muted);}if(Step=="magnet")Button(p,"confirmMagnet","锁定本指磁光布局",()=>CompleteFinger(active));Label(p,Step=="file"?"在指尖前缘左右锉动，停住不会完成。":Step=="bond"?"从甲根按住，平稳向指尖推；从中间开始不能压合。":Step=="decor"?"点击甲面设计中装饰的位置完成落位。":"按住在甲面各区域来回操作，先亲手完成一指。",14,Rose);Button(p,"assist","辅助处理本手其余指",Assist,false,ids.Any(i=>i/5==active/5&&data.session.work[i].done.Contains(Step)));}
  Button(p,"nextStage","本阶段完成，继续 →",NextStage,true,ids.All(i=>data.session.work[i].done.Contains(Step)));var hist=Row(p);Button(hist,"undoWork","撤销本阶段",()=>Undo(false));Button(hist,"redoWork","重做",()=>Undo(true));Button(p,"talk","回看顾客需求",()=>ShowConsultation());
 }
 void ResultUI(Transform p){Label(p,"这份心意，\n刚刚好。",30);Label(p,"100 / 100",30,Rose);Label(p,Who.review,15,Muted);if(Who.lesson>0)Label(p,"本课技法："+catalog.lessons[Who.lesson-1].badge+"\n领取收入后解锁下一课。",15,Rose);foreach(var group in new[]{new[]{"色系与透感","painted","palette","material"},new[]{"重点工艺","effect","features"},new[]{"日常实用","shape","length","comfort"}}){Label(p,"✓ "+group[0],17);Label(p,string.Join(" · ",Rules.Checks(Who,Design).Where(x=>group.Contains(x.key)).Select(x=>x.label)),13,Muted);}Label(p,"✓ 服务完成度",17);Label(p,"施工与三轮固化已按实际完成记录检查。",13,Muted);Button(p,"resultReference","对照参考与我的作品",()=>{Modal("参考与我的十指","comparison",out var b);Label(b,"顾客参考",18);MiniDesign(b,Who.reference);Label(b,"我的十指",18);MiniDesign(b,Design);});Button(p,"checkout","交付对话与收入",ShowCheckout,true);Button(p,"collect","收藏完整作品",SaveAlbum,true);Button(p,"photo","拍照下载",Photo);Button(p,"exportWork","导出可编辑作品",()=>Export(JsonUtility.ToJson(Design,true),Design.name+".json"));Button(p,"nextCustomer",Who.lesson>0?"回到学艺手册":"接待下一位",Who.lesson>0?(Action)ShowLessons:ShowBook);}
 void Modal(string title,string id,out RectTransform body){ReleaseContact();Clear(overlay);overlay.gameObject.SetActive(true);overlay.SetAsLastSibling();currentModal=id;modalCard=Panel(overlay,"Card",Paper);Rect(modalCard,Vector2.zero,Vector2.one,new Vector2(130,32),new Vector2(-130,-32));var top=Panel(modalCard,"Modal header",Paper);Rect(top,new Vector2(0,1),Vector2.one,new Vector2(0,-84),Vector2.zero);var titleText=Text(top,title,26);Rect(titleText.rectTransform,Vector2.zero,Vector2.one,new Vector2(24,8),new Vector2(-86,-22));var close=Button(top,"closeModal","关闭",CloseModal);Rect(close.GetComponent<RectTransform>(),new Vector2(1,0),Vector2.one,new Vector2(-78,22),new Vector2(-18,-22));var area=Panel(modalCard,"Body",Color.clear);Rect(area,Vector2.zero,Vector2.one,Vector2.zero,new Vector2(0,-84));body=Scroll(area);modalBody=body;Layout();}
 public void CloseModal(){currentModal=null;overlay.gameObject.SetActive(false);}
 public void ShowBook(){if(lampRemaining>0){Toast("先结束本轮照灯。");return;}Modal("今天，为谁留一点美？","book",out var p);Label(p,"六套十月新款、经典预约与记得你的常客。",15,Muted);foreach(var c in catalog.customers.Where(c=>c.lesson==0&&(string.IsNullOrEmpty(c.returnOf)||Rules.Access(catalog,data,c)))){var who=c;var card=Column(p,12);card.gameObject.AddComponent<LayoutElement>().minHeight=130;Label(card,c.name+"  ·  "+c.title,22);Label(card,c.limit+"  /  "+c.price+" 金币",14,Muted);if(!string.IsNullOrEmpty(c.returnOf)){var last=data.receipts.Last(r=>catalog.Find(r.client)?.name==c.name);Label(card,"第 "+(Rules.Visits(catalog,data,c)+1)+" 次见面 · 上次："+last.title,14,Rose);}Button(card,"appointment-"+c.id,"查看预约 →",()=>ShowAppointment(who));}}
 void ShowAppointment(Customer c){Modal(c.name+"的预约","appointment",out var p);Label(p,c.title,26);MiniDesign(p,c.reference);Label(p,"“"+c.quote+"”",18);Label(p,c.limit+"\n服务预算 "+c.price+" 金币",15,Muted);if(!string.IsNullOrEmpty(c.returnOf)){var count=Rules.Visits(catalog,data,c);var last=data.receipts.Last(r=>catalog.Find(r.client)?.name==c.name);Label(p,"我记得上次的「"+last.title+"」。这是第 "+(count+1)+" 次来访。\n完成回访额外心意 +"+(Math.Min(3,count)*5)+" 金币。",16,Rose);}if(data.session!=null)Label(p,"接待后替换当前服务。已收藏作品、收入与学艺进度保留。",13,Muted);Button(p,"accept-"+c.id,"接待顾客，聊聊需求 →",()=>Accept(c.id),true);}
 public void ShowConsultation(string selectedTopic=null){Modal("和"+Who.name+"聊聊","consultation",out var p);Label(p,Who.quote,20);Button(p,"talkReference","放大查看十指参考图",()=>ShowReference(Who.reference,Who.title,()=>ShowConsultation()));foreach(var t in Who.topics){var topic=t;Button(p,"topic-"+t.id,(data.session.consultation.Contains(t.id)?"✓ ":"＋ ")+t.label,()=>Answer(topic.id),false,!data.session.consultation.Contains(t.id));if(data.session.consultation.Contains(t.id)){Label(p,t.question,14,Rose);Label(p,t.answer,16);}}Label(p,"已记下 "+data.session.consultation.Count+" / 4 项需求",15,Muted);Button(p,"finishTalk","已记下需求，开始十指设计",()=>{CloseModal();Refresh();},true,data.session.consultation.Count==4);}
 void ShowReference(Design d,string title,Action back=null){Modal(title,"reference",out var p);Label(p,"完整十指 · 观察色彩、甲形与重点 · 位置由你安排",14,Muted);for(int i=0;i<10;i++){int j=i;var row=Row(p,180);Label(row,Rules.Finger(i),15);var tex=new Texture2D(128,256);AtelierView.RenderTexture2D(d.nails[i],tex,true);transient.Add(tex);var o=new GameObject("Reference nail",typeof(RectTransform),typeof(RawImage),typeof(LayoutElement));o.transform.SetParent(row,false);o.GetComponent<RawImage>().texture=tex;o.GetComponent<LayoutElement>().preferredHeight=180;Label(row,Rules.ShapeName(d.nails[i].shape)+"\n"+Rules.FinishName(d.nails[i].finish)+"\n"+Rules.PatternName(d.nails[i].pattern),15,Muted);}if(back!=null)Button(p,"referenceBack","回到顾客对话",back,true);}
 public void ShowLessons(){if(lampRemaining>0){Toast("先结束本轮照灯。");return;}Modal("从短甲开始，慢慢学会","lessons",out var p);Label(p,"五课循序练习。交付并领取收入后解锁下一课。\n原有预约与自由创作随时开放。",15,Muted);foreach(var lesson in catalog.lessons){var l=lesson;var c=catalog.Find(l.id);bool passed=data.receipts.Any(r=>r.client==l.id),access=Rules.Access(catalog,data,c);Label(p,c.lesson.ToString("00")+"  "+l.name,24);Label(p,l.hint,15,Muted);Label(p,passed?"✓ 已获得："+l.badge:access?"本课可练习":"完成上一课解锁",14,Rose);Button(p,"lesson-"+l.id,passed?"再练一次":access?"开始这课 →":"待解锁",()=>ShowAppointment(c),access,access);Space(p,6);}}
 public void ShowStyles(){Modal(catalog.season.title,"styles",out var p);Label(p,"更新于 "+catalog.season.date+" · 有日期的编辑选款",14,Muted);foreach(var c in catalog.customers.Where(x=>x.id.StartsWith("trend-"))){var who=c;Label(p,c.title+"  /  "+Rules.FinishName(c.finish),24);MiniDesign(p,c.reference);Label(p,c.quote,15,Muted);var r=Row(p);Button(r,"try-"+c.id,"3D 试戴",()=>{CloseModal();screen="studio";Refresh();for(int i=0;i<10;i++)view.Apply(i,who.reference.nails[i]);view.Focus("both");});Button(r,"style-"+c.id,"查看预约",()=>ShowAppointment(who));}Label(p,"选款参考",18);foreach(var s in catalog.season.sources){var source=s;Button(p,"source-"+s.name,s.name,()=>Application.OpenURL(source.url));}}
 public void ShowStudio(){if(lampRemaining>0){Toast("先结束本轮照灯。");return;}Modal("把小小工作室，慢慢变成你的","studio",out var p);Label(p,Rules.Balance(data)+" 可用金币",28,Rules.ColorOf("#a57839"));Label(p,"累计收入 "+data.receipts.Sum(r=>r.total)+" · 已添置 "+data.purchases.Sum(x=>x.price),14,Muted);foreach(var item in catalog.shop){var it=item;Label(p,item.name,22);Label(p,item.description,15,Muted);Button(p,"buy-"+item.id,Rules.Own(data,item.id)?"✓ 已解锁":item.price+" 金币 · 解锁",()=>{Transaction(()=>Rules.Buy(catalog,data,it.id));ApplyStudio();ShowStudio();},false,!Rules.Own(data,item.id)&&Rules.Balance(data)>=item.price);}
  Label(p,"摆在工作台上",24);Toggle(p,"鼠尾草工作垫",data.studio.mat=="sage-mat",v=>{if(!Rules.Own(data,"sage-mat")){Toast("先解锁工作垫。");return;}Transaction(()=>data.studio.mat=v?"sage-mat":"default");ApplyStudio();ShowStudio();});Toggle(p,"玫瑰铜托盘",data.studio.tray=="rose-tray",v=>{if(!Rules.Own(data,"rose-tray")){Toast("先解锁托盘。");return;}Transaction(()=>data.studio.tray=v?"rose-tray":"default");ApplyStudio();ShowStudio();});Toggle(p,"陈列与托盘摆在左侧",data.studio.layout=="left",v=>{Transaction(()=>data.studio.layout=v?"left":"right");ApplyStudio();ShowStudio();});if(Rules.Own(data,"display")){Label(p,"陈列我的作品",18);foreach(var work in data.album){var w=work;Button(p,"display-"+w.id,(data.studio.display==w.id?"✓ ":"")+w.name,()=>{Transaction(()=>data.studio.display=w.id);ApplyStudio();ShowStudio();});}Button(p,"displayNone","暂不放作品",()=>{Transaction(()=>data.studio.display=null);ApplyStudio();});}Label(p,"先在交付页收藏完整作品，再选择陈列。",13,Muted);Button(p,"viewStudio","看看布置好的工作台 →",()=>{freeMode=false;screen="studio";CloseModal();Refresh();view.Focus("studio");},true);}
 public void ShowCheckout(){Modal("谢谢你，记住了我的期待","checkout",out var p);Label(p,Who.review,20);var r=Rules.Reward(Who,data.session);Label(p,"服务 "+r.service+" + 打赏 "+r.tip+" = "+r.total+" 金币",24,Rose);if(r.loyalty>0)Label(p,"其中常客额外心意 +"+r.loyalty+" 金币",15);bool claimed=data.receipts.Any(x=>x.id==data.session.id);Button(p,"claim",claimed?"✓ 已入账，不会重复领取":"收下心意与收入",Claim,true,!claimed);if(Who.lesson>0)Button(p,"afterLesson","回学艺手册看下一课",ShowLessons);}
 public void ShowAlbum(){Modal("收藏每一次心意","album",out var p);if(data.album.Count==0)Label(p,"完成服务或自由创作后，收藏第一套完整十指。",17,Muted);foreach(var entry in data.album){var w=entry;Label(p,w.name,22);MiniDesign(p,w.design);var r=Row(p);Button(r,"albumOpen-"+w.id,"在自由创作中继续编辑",()=>{Transaction(()=>{data.free=Rules.Copy(w.design);data.free.id=Rules.Id();data.free.name=w.name+" · 副本";});freeMode=true;screen="free";CloseModal();undo.Clear();Refresh();});Button(r,"albumExport-"+w.id,"导出作品",()=>Export(JsonUtility.ToJson(w.design,true),w.name+".json"));}}
 public void ShowSettings(){Modal("声音、存档与作品备份","settings",out var p);Toggle(p,"静音",data.muted,v=>{data.muted=v;music.volume=v?0:data.volume;sfx.mute=v;contact.mute=v;Save();ShowSettings();});Label(p,"工作室伴奏",22);Choice(p,"曲目",new[]{"0","1","2","3","4","5"},data.track.ToString(),v=>new[]{"宁静的微光","宁静治愈","治愈钢琴","治愈少女","治愈时光","治愈系少女"}[int.Parse(v)],v=>Music(int.Parse(v)));Button(p,"musicToggle",music.isPlaying?"暂停伴奏":"播放伴奏",()=>{if(music.isPlaying)music.Pause();else if(music.clip)music.UnPause();else Music(data.track);ShowSettings();});Slider(p,"音乐音量",data.volume,0,1,v=>{data.volume=v;music.volume=data.muted?0:v;ScheduleSave();},false);Label(p,"存档与迁移",22);Label(p,"Unity 存档独立保存在本机。网页存档不会自动读取；可从原游戏导出作品或工作室备份，再导入这里。\n导入先校验，失败不会覆盖原记录。",14,Muted);Button(p,"exportAll","导出完整 Unity 备份",()=>Export(Rules.Json(data),"指间诗-Unity完整备份.json"));Button(p,"importFile","选择网页 / Unity JSON 备份",OpenImport);Input(p,"或粘贴 JSON 文件的完整路径",filePath,v=>filePath=v);Button(p,"importPath","从此路径导入",()=>{try{ImportText(File.ReadAllText(filePath));}catch(Exception e){Toast("读取失败："+e.Message,7);}});Label(p,"本机存档位置：\n"+store.PathName,12,Muted);Button(p,"openSaveFolder","打开存档文件夹",()=>Application.OpenURL("file:///"+Path.GetDirectoryName(store.PathName).Replace('\\','/')));Button(p,"help","操作：鼠标 / 键盘 / 触屏",()=>{Modal("慢慢完成每一指","help",out var b);Label(b,"点下方选指。设计时点击选色、设置甲形、拖动装饰；画笔和橡皮可直接在甲面拖画。\n施工时按提示移动工具，亲手完成本手一指后可辅助其余指。两手分别照灯，提前取手不算固化。\n右键旋转，滚轮缩放。触屏先点旋转查看，再切回操作。\nCtrl+Z 撤销，Ctrl+Y 重做，Tab 切换按钮，Enter 确认。",18);});}
 public void Toast(string text,float seconds=3.5f){if(!toastObject){Debug.Log(text);return;}toastText.text=text;toastObject.SetActive(true);toastObject.transform.SetAsLastSibling();toastUntil=Time.unscaledTime+seconds;}
 public void Photo(){CloseModal();view.Focus("both");StartCoroutine(PhotoRoutine());}
 IEnumerator PhotoRoutine(){yield return new WaitForEndOfFrame();var tex=ScreenCapture.CaptureScreenshotAsTexture();ExportBytes(tex.EncodeToPNG(),"指间诗-作品.png","image/png");Destroy(tex);PlaySound("camera-0");}
 void Export(string json,string name)=>ExportBytes(System.Text.Encoding.UTF8.GetBytes(json),name,"application/json");
 void ExportBytes(byte[] bytes,string name,string mime){
 #if UNITY_WEBGL && !UNITY_EDITOR
 AtelierBrowser.Download(Convert.ToBase64String(bytes),name,mime);
 #else
 string folder=Path.Combine(Application.persistentDataPath,"Exports");Directory.CreateDirectory(folder);string path=Path.Combine(folder,Sanitize(name));File.WriteAllBytes(path,bytes);Toast("已导出："+path,7);
 #endif
 }
 string Sanitize(string s){foreach(char c in Path.GetInvalidFileNameChars())s=s.Replace(c,'_');return s;}
 void OpenImport(){
 #if UNITY_WEBGL && !UNITY_EDITOR
 AtelierBrowser.Pick(gameObject.name);
 #elif UNITY_EDITOR
 string path=UnityEditor.EditorUtility.OpenFilePanel("导入指间诗备份","","json");if(path.Length>0)ImportText(File.ReadAllText(path));
 #else
 string path=AtelierBrowser.OpenNative();if(!string.IsNullOrEmpty(path))ImportText(File.ReadAllText(path));
 #endif
 }
 public void ImportText(string text){var previous=Rules.Copy(data);bool wasBlocked=store.blocked;try{if(text.Length>20000000)throw new Exception("备份超过20MB");data=AtelierImport.Merge(catalog,data,text);store.blocked=false;store.Save(data);ApplyStudio();CloseModal();freeMode=false;screen=data.session?.phase??"home";Refresh();Toast("备份已恢复，原记录另存为 .bak。",7);}catch(Exception e){data=previous;store.blocked=wasBlocked;Toast("导入失败，原记录保留："+e.Message,8);}}
 }
